import{_ as a,o as n,c as r,j as e,a as d}from"./chunks/framework.Bd7kzaCy.js";const m=JSON.parse('{"title":"D.02　知识、概念、语境与认识位置","description":"","frontmatter":{"title":"D.02　知识、概念、语境与认识位置"},"headers":[],"relativePath":"theory/appendix-d/d-02.md","filePath":"theory/appendix-d/d-02.md"}'),l={name:"theory/appendix-d/d-02.md"};function o(s,t,p,i,c,u){return n(),r("div",null,[...t[0]||(t[0]=[e("div",{class:"theory-source"},[e("h1",{id:"section-d-02",tabindex:"-1"},[d("D.02　知识、概念、语境与认识位置 "),e("a",{class:"header-anchor",href:"#section-d-02","aria-label":'Permalink to "D.02　知识、概念、语境与认识位置 {#section-d-02}"'},"​")]),e("p",null,"正文连接：§2.1—2.7；§4.8；§16.6、16.15。研究入口：02.01—02.08。"),e("p",null,"经验、推理、实践、身体经验、文本解释和规范论证各有证明责任。形式推导要公开前提与规则；经验判断要说明观察怎样支持主张；解释性研究要把文本、语境和竞争读法放在一起；规范论证要说明理由与受影响位置。它们可以互相约束，不能被统一压成一个预测成绩。"),e("p",null,"证伪、范式与研究纲领提供不同尺度的批评。一个局部反例可能否定某个辅助假设，也可能要求调整对象或测量；是否足以动摇更广理论，要看原命题的范围和依赖。换一个问题可以产生有价值的新研究，但不能把新结果倒填为旧检验成功。实用、可行动、获得共识和为真也不是同一标准。"),e("p",null,"语言既描述也可能构成行动：承诺、命名、授予资格和报告事实所需的说话位置、规则与证据不同。一个人说“我同意”可能是真实表达，也可能在特定压力下不足以构成有效授权。理解其话语意义，不能替代对制度条件的检查；语言失配也不能直接诊断人格或智力。"),e("p",null,"认识位置影响谁能接近材料、什么问题可被提出、谁的表达更容易被相信。改善听取、翻译和安全表达的条件，可以增加可用知识；被排斥者的发言仍应按具体主张审查，既不先验失格，也不获得自动真值特权。保护性不公开可以与可信核验并存。"),e("p",null,"允许不同方法互相纠正，仍需保留它们真正不同的理论承诺。位置影响知识生产不推出对象可被任意制造，理由可能参与因果解释也不取消意义理解的独立任务。可靠日期材料能够纠正一个记忆中的日期，同时保留讲述资格和经历的意义；承认讲述者的地位，不使每一事实命题自动为真。"),e("p",null,"专题定位：02.01 经验论与理性论：休谟、笛卡尔等；02.02 证伪、范式与研究纲领：波普尔、库恩、拉卡托斯；02.03 实用主义：皮尔士、詹姆斯、杜威；02.04 实在论、建构论与批判实在论；02.05 现象学：胡塞尔、海德格尔、梅洛-庞蒂；02.06 解释学：狄尔泰、伽达默尔、利科；02.07 语言、概念与语境：维特根斯坦、奥斯汀等；02.08 认识不正义与位置性知识。")],-1)])])}const f=a(l,[["render",o]]);export{m as __pageData,f as default};
